package xyz.jovanstoiljkovic.isa.services;import org.springframework.data.repository.CrudRepository;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import xyz.jovanstoiljkovic.isa.models.Song;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.Paths;import java.util.ArrayList;import java.util.List;import java.util.Optional;@Servicepublic class SongService extends BaseService<Song>{    private final Path folderPath = Paths.get(System.getProperty("user.dir"), "src", "main", "resources", "songs");    public SongService(CrudRepository<Song, Long> repo) {        super(repo);    }    public Optional<Song> create(MultipartFile songFile, Song song){        Path filePath = folderPath.resolve(song.getName() + ".mp3");        song.setUrl("songs/" + song.getName() + ".mp3");        if(songFile != null){            try{                if(!Files.exists(folderPath)) Files.createDirectories(folderPath);                songFile.transferTo(filePath.toFile());            }            catch (Exception e){                e.printStackTrace();                return Optional.empty();            }        }        repo.save(song);        return Optional.of(song);    }    public Optional<Song> updatePut(Long id, MultipartFile songFile, Song song){        Optional<Song> existing = this.findById(id);        if (existing.isEmpty()) return Optional.empty();        song.setId(id);        song.setUrl("songs/" + song.getName() + ".mp3");        if(songFile != null){            Path oldFilePath = folderPath.resolve(existing.get().getName() + ".mp3");            if(oldFilePath.toFile().delete()){                System.out.println("Deleted file successfully");            }            else{                System.out.println("Failed to delete file :<");            }            Path filePath = folderPath.resolve(song.getName() + ".mp3");            try{                if(!Files.exists(folderPath)) Files.createDirectories(folderPath);                songFile.transferTo(filePath.toFile());            }            catch (Exception e){                e.printStackTrace();                return Optional.empty();            }        }        Song savedSong = repo.save(song);        if(savedSong == null) return Optional.empty();        return Optional.of(savedSong);    }    public List<Song> search(String searchString){        String searchLower = searchString.toLowerCase();        List<Song> songs = new ArrayList<>();        repo.findAll().forEach(song -> {            if(                song.getName().toLowerCase().contains(searchLower) ||                (song.getAlbum() != null && song.getAlbum().getName().toLowerCase().contains(searchLower)) ||                (song.getArtist() != null && song.getArtist().getName().toLowerCase().contains(searchLower))            ) songs.add(song);        });        return songs;    }}